#!/usr/bin/env python3
# In a notebook, do not edit this file. It is generic - the template's, listed
# in .claude/notebook/manifest.txt - and the update skill replaces it; the
# notebook's pre-commit hook refuses a commit that changes it. To extend:
#   - a setting or an audit rule: .scripts/notebook_config.py
#   - an operation or a check of the notebook's own: a script of its own in
#     .scripts/ that imports this one, never a copy of it
#   - a rule for one type: that type's declaration in Types/
#   - a fix every notebook needs: ask the template for it, with an issue -
#     .claude/notebook/requests.md
# The whole table: .claude/notebook/upstream.md, "The outlets".
"""Compare the type system as DECLARED against the pages as they ARE.

`Types/*.md` declares each type - its folder, its required fields and the
fields that may apply. `Views/Types.base` is the self-updating table of those
declarations; this is the half a base cannot do, because a base lists and
does not validate.

What it reports, and the first is what went unnoticed for months:

  - a `type:` in use that no Types/ page declares
  - a declared required field that pages of that type do not carry
  - a field in use that the type declares neither required nor optional
  - a declared type with no pages at all (reported, not counted: declaring early is normal)
  - pages living outside their type's declared folder
  - an entity type whose declared `sections:` drop Known or My reading
  - pages missing a heading their type declares (a browse, not counted)
  - a field declared in `links:` holding plain text, or a link landing on a
    page of another type than the one declared (a dangling link is a browse:
    it means named, not yet filed)

Paths derive from this script's own location, as everywhere here.
"""
import os, pathlib, re, sys

# `python3 -I` isolates sys.path, which drops this script's own directory -
# so the config beside it is not importable without putting it back.
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import notebook_config
import notebook

VAULT = pathlib.Path(__file__).resolve().parents[1]
SKIP = {".obsidian", ".scripts", ".claude", ".git"}
TYPES = notebook_config.TYPES_DIR

def frontmatter(text):
    m = re.match(r"---\n(.*?)\n---", text, re.S)
    if not m:
        return {}
    out, body = {}, m.group(1) + "\n"
    for key, val in re.findall(r"^([a-z_]+):[ \t]*(.*)$", body, re.M):
        val = val.strip()
        # An inline list, `key: [a, b]`, is a list - `sections: []` an empty one.
        out[key] = [x.strip().strip("\"'") for x in val[1:-1].split(",") if x.strip()] \
            if val.startswith("[") and val.endswith("]") else (val or [])
    for key in list(out):
        if out[key] == []:
            b = re.search(rf"^{key}:[ \t]*\n((?:[ \t]*-[ \t]*\S.*\n?)+)", body, re.M)
            if b:
                out[key] = [l.strip().lstrip("-").strip().strip("\"'")
                            for l in b.group(1).splitlines() if l.strip()]
    for key in list(out):
        if out[key] == []:
            b = re.search(rf"^{key}:[ \t]*\n((?:[ \t]+[a-z_]+:.*\n?)+)", body, re.M)
            if b:
                out[key] = {k.strip(): v.strip() for k, v in
                            (l.split(":", 1) for l in b.group(1).splitlines() if ":" in l)}
    return out

# Fields the contract applies to EVERY type, so no declaration has to re-list
# them - and re-listing them on each type page is a copy nothing compares.
# See .claude/notebook/registry.md.
UNIVERSAL = {"aliases", "source", "ambiguous_names", "common_names", "tags"}

declared, pages, by_name = {}, [], {}
for p in sorted(VAULT.rglob("*.md")):
    if any(x in p.parts for x in SKIP):
        continue
    fm = frontmatter(p.read_text(encoding="utf-8", errors="replace"))
    by_name.setdefault(p.stem, []).append((p, fm.get("type")))
    if fm.get("type") == "type":
        declared[fm.get("declares", p.stem)] = fm
    elif fm.get("type"):
        pages.append((p, fm))

problems = 0

def say(head, lines):
    global problems
    if lines:
        problems += len(lines)
        print(f"\n{head} ({len(lines)}):")
        for l in lines:
            print(f"  {l}")

in_use = {}
for p, fm in pages:
    in_use.setdefault(fm["type"], []).append((p, fm))

say("a `type:` in use that no Types/ page declares",
    [f"{t}  on {len(v)} page(s), e.g. {v[0][0].relative_to(VAULT)}"
     for t, v in sorted(in_use.items()) if t not in declared])

# Reported, NOT a problem. Declaring a type before anything of that kind is
# filed is normal and often right (.claude/notebook/promotion.md): the first
# instance then arrives already having somewhere to go. A check that failed
# here would veto the user's legitimate choice.
empty = sorted(set(declared) - set(in_use))
if empty:
    print(f"\ndeclared with no pages yet ({len(empty)}) - fine, not a fault:")
    for t in empty:
        print(f"  {t}")

missing = []
for t, v in sorted(in_use.items()):
    for key in [k for k in declared.get(t, {}).get("required", []) if k != "type"]:
        bad = [p for p, fm in v if key not in fm]
        if bad:
            missing.append(f"{t}.{key}  missing on {len(bad)}/{len(v)}, e.g. {bad[0].relative_to(VAULT)}")
say("a declared REQUIRED field that pages do not carry", missing)

undeclared = []
for t, v in sorted(in_use.items()):
    d = declared.get(t, {})
    known = set(d.get("required", [])) | set(d.get("optional", [])) | {"type"} | UNIVERSAL \
        | ({"parent"} if d.get("parents") else set())     # written from the path (graph.md, "Ownership")
    seen = {}
    for p, fm in v:
        for k in fm:
            if k not in known:
                seen.setdefault(k, []).append(p)
    for k, ps in sorted(seen.items()):
        undeclared.append(f"{t}.{k}  on {len(ps)} page(s), declared neither required nor optional, e.g. {ps[0].relative_to(VAULT)}")
say("a field in use that its type does not declare", undeclared)

# A declaration is also the page template (registry.md): `sections:` is the
# headings every page of the type has. An entity type keeps Known and My
# reading, because attribution is structural; `sections: []` is a verbatim page.
# A relation page records a fact rather than a thing, and a generated page is
# a projection's output with a layout of its own, so neither owes My reading.
def layout(d):
    s = d.get("sections")
    if isinstance(s, list) and (s or "sections" in d):
        return s
    return ["Known"] if d.get("relation") == "true" else ["Known", "My reading"]

say("an entity type whose layout drops Known or My reading",
    [f"{t}  declares sections: without {' or '.join(h for h in ('Known', 'My reading') if h not in layout(d))}"
     for t, d in sorted(declared.items())
     if not d.get("ledger") and d.get("relation") != "true" and d.get("generated") != "true"
     and layout(d) and not {"Known", "My reading"} <= set(layout(d))])

# Reported, NOT counted. A page older than its type's layout is the same blind
# spot as an optional field (registry.md): adding an empty heading to clear the
# line states nothing, so this is a browse. Only a layout a type declares itself
# is compared - the default is a convention, and a host may add My reading only
# once there is a reading to put in it.
short = []
for t, v in sorted(in_use.items()):
    if not isinstance(declared.get(t, {}).get("sections"), list):
        continue
    # The headings as notebook.py reads them: `- <heading>: <type>` is the
    # heading <heading>, filled by owned pages (graph.md, "Ownership").
    for h in notebook.registry().get(t, {}).get("sections") or layout(declared[t]):
        lacking = [p for p, fm in v
                   if not re.search(rf"^## {re.escape(h)}[ \t]*$", p.read_text(encoding="utf-8", errors="replace"), re.M)]
        if lacking:
            short.append(f"{t}  `## {h}` missing on {len(lacking)}/{len(v)}, e.g. {lacking[0].relative_to(VAULT)}")
if short:
    print(f"\npages without a heading their type declares ({len(short)}) - a browse, not a fault:")
    for l in short:
        print(f"  {l}")

# A field in `links:` is a typed edge (graph.md): each value is a wikilink, and
# lands on a page of the declared type. Resolved by basename, or by path when
# the link carries one, the way Obsidian resolves it.
LINK = re.compile(r"^\[\[([^\]|#]+)(?:#[^\]|]*)?(?:\|[^\]]*)?\]\]$")

def target(name):
    if "/" in name:
        return [(p, t) for ps in by_name.values() for p, t in ps
                if p.relative_to(VAULT).with_suffix("").as_posix().endswith(name)]
    return by_name.get(name, [])

plain, off, dangling = [], [], []
for t, v in sorted(in_use.items()):
    links = declared.get(t, {}).get("links")
    if not isinstance(links, dict):
        continue
    for field, want in sorted(links.items()):
        for p, fm in v:
            vals = fm.get(field)
            for val in (vals if isinstance(vals, list) else [vals] if vals else []):
                val = val.strip().strip("\"'")
                m = LINK.match(val)
                if not m:
                    plain.append(f"{t}.{field}  {val!r} is not a link, on {p.relative_to(VAULT)}")
                    continue
                hits = target(m.group(1).strip())
                if not hits:
                    dangling.append(f"{t}.{field}  [[{m.group(1)}]] on {p.relative_to(VAULT)}")
                elif want != "any" and not any(ht == want for _, ht in hits):
                    off.append(f"{t}.{field}  [[{m.group(1)}]] is `{hits[0][1] or 'untyped'}`, declared {want}, "
                               f"on {p.relative_to(VAULT)}")
say("a field declared in `links:` holding plain text", plain)
say("a link in a `links:` field landing on a page of another type", off)
if dangling:
    print(f"\nlinks in `links:` fields with no page yet ({len(dangling)}) - named, not yet filed; a browse:")
    for l in dangling:
        print(f"  {l}")

# The graph view's groups are derived (notebook.py graph); a type with no
# group, or a group for a type nothing declares, means the derivation was
# skipped or the file was edited by hand. A browse: rerun `graph` to fix it.
gpath = VAULT / ".obsidian" / "graph.json"
if gpath.exists():
    import json
    try:
        have = {g.get("query", "") for g in json.loads(gpath.read_text()).get("colorGroups", [])}
    except ValueError:
        have = set()
    want_q = {f"[type:/^{re.escape(t)}$/]" for t, d in declared.items()
              if not d.get("ledger") and d.get("generated") != "true"}
    drift = sorted(f"no graph group for {q}" for q in want_q - have) + \
            sorted(f"graph group for no declared type: {q}" for q in have - want_q
                   if q.startswith("[type:/^"))
    if drift:
        print(f"\ngraph groups out of step with the declarations ({len(drift)}) - a browse; run `graph`:")
        for l in drift:
            print(f"  {l}")

# Ownership (graph.md, "Ownership"): where a page sits says what owns it.
# A top-level type's folder is at the vault root; an owned type's sits inside
# an entity folder - one page of its own, and the type folders of what it owns.
REG = notebook.registry()
wrong, owners, drift = [], [], []
for t, v in sorted(in_use.items()):
    d = REG.get(t)
    if not d:
        continue
    for p, fm in v:
        rel = p.relative_to(VAULT)
        if rel.parent == pathlib.Path("."):
            continue
        td = notebook._type_dir(p, d["folder"])
        if td is None:
            wrong.append(f"{rel}  is `{t}`, declared folder {d['folder']}/")
        elif not d["parents"] and td.parent != VAULT:
            owners.append(f"{rel}  is `{t}`, a top-level type, inside {td.parent.relative_to(VAULT)}/")
        elif d["parents"] and td.parent == VAULT:
            owners.append(f"{rel}  is `{t}`, owned by a {' or '.join(d['parents'])}, but nothing owns it")
        elif d["parents"]:
            o = notebook.owner_of(p, REG)
            if o is None:
                owners.append(f"{rel}  is in {td.parent.relative_to(VAULT)}/, which has no single page of its own")
            elif notebook._page_type(o) not in d["parents"]:
                owners.append(f"{rel}  is `{t}`, owned by `{notebook._page_type(o)}` {o.stem}; "
                              f"its declaration allows {' or '.join(d['parents'])}")
            elif str(fm.get("parent", "")).strip("\"'") != f"[[{o.stem}]]":
                drift.append(f"{rel}  parent: {fm.get('parent') or '(none)'}, but it sits under {o.stem}")
say("pages outside their type's declared folder", wrong)
say("pages under the wrong owner, or none", owners)
if drift:
    print(f"\nparent: out of step with where the page is ({len(drift)}) - a browse; run `notebook.py tree`:")
    for l in drift:
        print(f"  {l}")

# The declarations themselves (registry.md, "Ownership", "Names"): every
# {variable} a name pattern uses is set by its own type or a type above it,
# and the type's own is among them. One that leaves out a variable above it
# names its pages uniquely only among their siblings - a browse, since links
# to them then need the path form.
def chains(t, seen=()):
    """Each chain of types from a top-level one down to t. A type nested in
    itself sets nothing new - the nearest value of its own variable wins - so
    the chains through it are those through its other parents."""
    d = REG[t]
    out = []
    for par in [p for p in d["parents"] if p != t] or [None]:
        if par is None or par in seen or par not in REG:
            out.append([t])
        else:
            out += [c + [t] for c in chains(par, seen + (t,))]
    return out

decl, narrow = [], []
for t, d in sorted(REG.items()):
    for par in d["parents"]:
        if par not in REG:
            decl.append(f"{t}  parents: names {par}, which nothing declares")
    for layer in d["buckets"]:
        err = notebook.bucket_layer_error(layer)
        if err:
            decl.append(f"{t}  buckets: {err}")
    for s in d["prepared"]:
        if s not in d["sections"]:
            decl.append(f"{t}  prepared: {s}, which is not one of its sections")
    for head, child in d["slots"].items():
        if t not in REG[child]["parents"]:
            decl.append(f"{t}  section {head} holds {child}, whose parents: do not include {t}")
    used = set(re.findall(r"\{(\w+)\}", d["pattern"]))
    if d["identity"] == "none":
        if not d["parents"]:
            decl.append(f"{t}  identity: none - one per owner - but nothing owns it (no parents:)")
    elif d["identity"] not in used:
        decl.append(f"{t}  name: {d['pattern']!r} leaves out its own {{{d['identity']}}}, so every page would share a name")
    for c in chains(t):
        scope = {REG[x]["identity"] for x in c} - {"none"}
        if used - scope:
            decl.append(f"{t}  name: {d['pattern']!r} uses {', '.join('{%s}' % v for v in sorted(used - scope))}, "
                        f"which nothing on {' > '.join(c)} sets")
        elif scope - used:
            narrow.append(f"{t}  name: {d['pattern']!r} leaves out {', '.join('{%s}' % v for v in sorted(scope - used))} "
                          f"from {' > '.join(c)}")
say("a declaration whose ownership or names do not hold together", decl)
if narrow:
    print(f"\nnames unique only among their siblings ({len(narrow)}) - a browse; links to them need the path:")
    for l in narrow:
        print(f"  {l}")

# Buckets (registry.md, "Buckets"): a page sits in the folders its name and
# fields put it in. Both are browses - `notebook.py tree` moves pages home,
# and a page a layer does not apply to is legal, and stays where the last
# layer that did left it.
away, loose = [], []
for t, v in sorted(in_use.items()):
    d = REG.get(t)
    if not d or not d["buckets"]:
        continue
    try:
        for p, fm in v:
            home = notebook._home(p, REG)
            if home is not None and home != p:
                away.append(f"{p.relative_to(VAULT)}  belongs in {home.parent.relative_to(VAULT)}/")
            n = len(notebook._buckets(d, p.stem, notebook.fields(p)))
            if n < len(d["buckets"]):
                loose.append(f"{p.relative_to(VAULT)}  fits {n} of {t}'s {len(d['buckets'])} bucket layers - a name a regex does not match, or a date field missing")
    except re.error:
        continue                    # reported with the declarations above
if away:
    print(f"\npages not in the bucket their name or fields put them in ({len(away)}) - a browse; run `notebook.py tree`:")
    for l in away:
        print(f"  {l}")
if loose:
    print(f"\npages a bucket layer does not apply to ({len(loose)}) - a browse; they stay where the last layer that did left them:")
    for l in loose:
        print(f"  {l}")

# Names that are not what their pattern makes of where the page is: older
# pages keep theirs (a ledger entry's name never changes), so a browse.
offname = []
for t, v in sorted(in_use.items()):
    d = REG.get(t)
    if not d or d["pattern"] == "{%s}" % d["identity"]:
        continue
    for p, fm in v:
        want = notebook._filename(d["pattern"].format_map(
            {**{k: "{%s}" % k for k in re.findall(r"\{(\w+)\}", d["pattern"])}, **notebook.variables(p, REG)}))
        if want != p.stem:
            offname.append(f"{p.relative_to(VAULT)}  would be named {want}.md")
if offname:
    print(f"\nnames that differ from their type's pattern ({len(offname)}) - a browse; older pages keep theirs:")
    for l in offname:
        print(f"  {l}")

print(f"\n{len(declared)} types declared, {len(in_use)} in use across {len(pages)} pages, "
      f"{problems} problem(s)")
sys.exit(1 if problems else 0)
